/* Additional decision tools; all user data stays in this browser. */
let comparison=new Set(), sortMode='default', pickedMeals=read('shike-meals',[]);
const baseRender=render, baseDetail=showDetail;
const extraDialog=document.createElement('dialog');extraDialog.id='extra-dialog';document.body.append(extraDialog);
const tray=document.createElement('div');tray.className='compare-tray hidden';tray.setAttribute('aria-live','polite');document.body.append(tray);
const toolsRow=document.createElement('div');toolsRow.className='smart-tools';toolsRow.innerHTML='<span class="note" id="result-count"></span><div><button class="text-btn" id="review-entry">✎ 写点评</button> · <button class="text-btn" id="meal-history">用餐足迹</button> <select id="sort-mode" aria-label="菜品排序"><option value="default">综合推荐</option><option value="price">价格从低到高</option><option value="wait">排队时间最短</option><option value="score">评分从高到低</option></select></div>';
$('#cards').before(toolsRow);
const scene=document.createElement('div');scene.className='scenes';scene.innerHTML='<button data-scene="rush">⚡ 赶着上课</button><button data-scene="save">🌱 月底省钱</button><button data-scene="spicy">🌶 想吃辣的</button>';
$('#chooser .note').after(scene);
$('#recommend').insertAdjacentHTML('beforebegin','<label for="maxwait">最多愿意排多久</label><select id="maxwait"><option value="99">时间充裕 · 不限制</option><option value="5">5 分钟以内 · 赶课模式</option><option value="3">3 分钟以内 · 即刻开吃</option></select>');
$('#chooser').insertAdjacentHTML('beforeend','<div class="profile-line"><span class="note">偏好自动记在这台设备</span><button id="reset-prefs">重置偏好</button></div><div id="recent-choice" class="recent-choice hidden"></div>');
function storeExtra(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('本次可体验，但浏览器未允许持久保存')}}
function savePrefs(){storeExtra('shike-prefs',{budget:$('#budget').value,taste:$('#taste').value,wait:$('#maxwait').value});lastPick=null;$('#recommend-result').classList.add('hidden');$('#recommend').textContent='帮我选一餐 ↗'}
const prefs=read('shike-prefs',{});for(const [id,key] of [['budget','budget'],['taste','taste'],['maxwait','wait']]){if([...$('#'+id).options].some(o=>o.value===prefs[key]))$('#'+id).value=prefs[key];$('#'+id).addEventListener('change',savePrefs)}
$('#reset-prefs').onclick=()=>{$('#budget').value='15';$('#taste').value='all';$('#maxwait').value='99';savePrefs();toast('已恢复默认偏好')};
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{const scenes={rush:['15','all','3'],save:['10','all','99'],spicy:['25','spicy','99']};const v=scenes[b.dataset.scene];$('#budget').value=v[0];$('#taste').value=v[1];$('#maxwait').value=v[2];savePrefs();recommend()});
render=function(){baseRender();const cards=[...$('#cards').children].filter(c=>c.classList.contains('card'));if(sortMode!=='default'){cards.sort((a,b)=>{const da=dishes.find(d=>d.id===+a.querySelector('[data-detail]').dataset.detail),db=dishes.find(d=>d.id===+b.querySelector('[data-detail]').dataset.detail);return sortMode==='score'?db.score-da.score:da[sortMode]-db[sortMode]});cards.forEach(c=>$('#cards').append(c))}cards.forEach(c=>{const id=+c.querySelector('[data-detail]').dataset.detail;const button=document.createElement('button');button.className='compare-add';button.dataset.compare=id;button.setAttribute('aria-pressed',comparison.has(id));button.textContent=comparison.has(id)?'✓ 已加入对比':'＋ 加入对比';c.querySelector('.card-body').append(button)});$('#result-count').textContent=`找到 ${cards.length} 道菜 · 最多可对比 3 道`;};
$('#sort-mode').onchange=()=>{sortMode=$('#sort-mode').value;render()};$('#search').oninput=()=>render();
function updateTray(){tray.classList.toggle('hidden',comparison.size===0);tray.innerHTML=`<div class="tray-copy"><b>选餐对比 · ${comparison.size}/3</b><br><small>${[...comparison].map(id=>dishes.find(d=>d.id===id).name).join(' / ')}</small></div><button id="clear-compare" aria-label="清空对比">清空</button><button class="primary" id="open-compare" ${comparison.size<2?'disabled':''}>${comparison.size<2?'再选一道':'开始对比 →'}</button>`;$('#clear-compare').onclick=()=>{comparison.clear();render();updateTray()};$('#open-compare').onclick=showComparison}
function openExtra(title,body,wide=false){extraDialog.classList.toggle('compare-dialog',wide);extraDialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-close aria-label="关闭">×</button></div>${body}`;if(!extraDialog.open)extraDialog.showModal()}
function showComparison(){const ds=[...comparison].map(id=>dishes.find(d=>d.id===id));const cheapest=Math.min(...ds.map(d=>d.price)),fastest=Math.min(...ds.map(d=>d.wait));const rows=[['价格',d=>`<span class="${d.price===cheapest?'best':''}">¥${d.price}${d.price===cheapest?' · 最省钱':''}</span>`],['等待',d=>`<span class="${d.wait===fastest?'best':''}">约 ${d.wait} 分钟${d.wait===fastest?' · 最快':''}</span>`],['口碑',d=>`${d.score?'★ '+d.score.toFixed(1):'样本不足，暂不评分'}<br><small>${d.count} 条示例点评</small>`],['口味',d=>d.taste==='mild'?'清淡 / 不辣':'香辣'],['去哪吃',d=>`${d.hall}<br>${d.window}`],['留意',d=>d.issue],['做决定',d=>`<button class="primary" data-choose="${d.id}">就吃这道</button>`]];openExtra('纠结的几道菜，放一起比',`<p class="dialog-sub">价格、等待与口味一起看，找到更适合此刻的选择。全部为演示数据。</p><div class="table-wrap"><table class="compare-table"><thead><tr><th>对比维度</th>${ds.map(d=>`<th>${d.emoji}<br>${d.name}</th>`).join('')}</tr></thead><tbody>${rows.map(([name,fn])=>`<tr><th scope="row">${name}</th>${ds.map(d=>`<td>${fn(d)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">窄屏可横向滑动对比表。</p>`,true)}
document.addEventListener('click',e=>{const compare=e.target.closest('[data-compare]'),choose=e.target.closest('[data-choose]'),review=e.target.closest('[data-write-review]');if(compare){const id=+compare.dataset.compare;if(comparison.has(id))comparison.delete(id);else if(comparison.size<3)comparison.add(id);else{toast('最多对比 3 道，先移除一道再添加');return}render();updateTray()}if(choose)chooseMeal(+choose.dataset.choose);if(review){extraDialog.close();showDetail(+review.dataset.writeReview);$('#review-form').scrollIntoView({behavior:'smooth',block:'start'});$('#review-text').focus({preventScroll:true})}});
function reviewPicker(){openExtra('今天吃了什么？',`<p class="dialog-sub">先选菜品，再分享具体体验。点评仅保存在本机。</p><div class="choice-list">${dishes.map(d=>`<button class="choice-item" data-write-review="${d.id}"><span>${d.emoji}</span><span><b>${d.name}</b><small>${d.hall} · ${d.window}</small></span></button>`).join('')}</div>`)}
$('#write-general').onclick=reviewPicker;$('#review-entry').onclick=reviewPicker;
showDetail=function(id){baseDetail(id);const d=dishes.find(d=>d.id===id);$('.detail-food').insertAdjacentHTML('afterend',`<div class="detail-actions"><button class="primary" data-choose="${id}">就吃这道 · ¥${d.price}</button><button class="chip" data-compare="${id}">加入 / 移除对比</button></div>`)};
function recentChoice(){const item=pickedMeals[0];if(!item)return;const d=dishes.find(d=>d.id===item.id);if(!d)return;$('#recent-choice').classList.remove('hidden');$('#recent-choice').innerHTML=`<b>最近选了 ${d.emoji} ${d.name}</b><br>${d.hall} · ${d.window}<br><button class="text-btn" id="recent-review">吃完来点评 →</button>`;$('#recent-review').onclick=()=>{showDetail(d.id);$('#review-form').scrollIntoView({behavior:'smooth'})}}
function chooseMeal(id){const d=dishes.find(d=>d.id===id);pickedMeals=[{id,time:new Date().toISOString()},...pickedMeals].slice(0,30);storeExtra('shike-meals',pickedMeals);extraDialog.close();$('#detail').close();recentChoice();toast(`已记下：${d.name}，去${d.hall} ${d.window}`)}
$('#meal-history').onclick=()=>openExtra('我的用餐足迹',`<p class="dialog-sub">记录“就吃这道”的选择，不代表已经购买或实际用餐。仅保存在本机。</p><div class="record-list">${pickedMeals.length?pickedMeals.map(item=>{const d=dishes.find(d=>d.id===item.id);return d?`<div class="record-item"><span style="font-size:28px">${d.emoji}</span><span style="flex:1"><b>${d.name}</b><br><small>${new Date(item.time).toLocaleString('zh-CN')} · ¥${d.price}</small></span><button class="text-btn" data-write-review="${d.id}">去点评</button></div>`:''}).join(''):'<p class="note">还没有记录。在推荐或详情中点“就吃这道”，留下第一条选餐足迹。</p>'}</div>`);
recommend=function(){const budget=+$('#budget').value,taste=$('#taste').value,wait=+$('#maxwait').value;const list=dishes.filter(d=>d.price<=budget&&(taste==='all'||d.taste===taste)&&d.wait<=wait).sort((a,b)=>(b.score-b.wait*.03)-(a.score-a.wait*.03));$('#recommend-result').classList.remove('hidden');if(!list.length){$('#recommend-result').innerHTML='暂时没有同时满足预算、口味和等待时间的菜品。可以提高预算或放宽排队时间。';return}let index=list.findIndex(d=>d.id===lastPick);const d=list[(index+1)%list.length];lastPick=d.id;$('#recommend-result').innerHTML=`<b>${d.emoji} 今天试试：${d.name}</b><br>¥${d.price}，预算还余 ¥${budget-d.price}；${d.taste==='mild'?'清淡不辣':'香辣口味'}；约等 ${d.wait} 分钟。<br><span class="note">匹配 ${list.length} 道 · 综合评分与等待时间排序</span><br><button class="text-btn" data-detail="${d.id}">看看窗口与点评 →</button><button class="primary" data-choose="${d.id}" style="margin-top:10px">就吃这道 ✓</button>`;$('#recommend').textContent=list.length>1?'换一道试试 ↻':'只有这一道匹配 · 再看一次'};
$('#recommend').onclick=()=>recommend();
$('#about-modal .concept').insertAdjacentHTML('beforeend','<h3>新增的决策闭环</h3><p>情境快捷选择 → 预算、口味与等待上限 → 可解释推荐 → 最多三道横向对比 → 确认选择 → 用餐足迹 → 回来点评。偏好、收藏、点评和足迹保存在当前设备。</p>');
render();recentChoice();
